() => {
      const SF = window.simitfirini, SEEDS = [1, 2, 3, 4, 5, 6];
      const out = { games: 0, won: 0, bankrupt: 0, timeup: 0, lira: 0, rep: 0, days: 0 };
      for (const seed of SEEDS) {
        SF.FLAGS.seed = seed;
        document.getElementById('bPlay').click();
        if (SF.S.seed !== seed || SF.S.day !== 1) throw new Error(`gate: seed ${seed} did not start a new game (seed ${SF.S.seed}, day ${SF.S.day})`);
        window.simitfiriniSim(200000);
        const S = SF.S;
        if (S.phase !== 'ended') throw new Error(`gate: seed ${seed} did not end (day ${S.day}, phase ${S.phase})`);
        out.games++; out[S.result === 'won' ? 'won' : S.result === 'bankrupt' ? 'bankrupt' : 'timeup']++;
        out.lira += Math.round(S.lira); out.rep += S.rep; out.days += S.day;
      }
      out.rep = Math.round(out.rep * 100) / 100;
      window.__gateM = out;
    }
